  ui_story_30090401_52_dialog_content = "<color=#FFFFFF>Guía y Consejos de Wispy</color>",
  ui_story_30090401_53_dialog_content = "<size=37><color=#FFFFFF>1. Coloca a Wispy en un lugar que no sea demasiado frío ni demasiado caliente.</color></size>",
  ui_story_30090401_A1_dialog_content = "<size=37><color=#FFFFFF>Intenta no hacer que se desprenda su pintura o que el mango se oxide.</color></size>",
  ui_story_30090401_X53_dialog_content = "<size=37><color=#FFFFFF>2. Limpie diariamente. Use una servilleta para limpiar ligeramente la superficie de la maleta.</color></size>",
  ui_story_30090401_A2_dialog_content = "<size=37><color=#FFFFFF>Si la maleta se sacude violentamente, espera hasta que se calme.</color></size>",
  ui_story_30090401_X54_dialog_content = "<size=37><color=#FFFFFF>3. No abras el maletín a la fuerza. Si debes abrirlo...</color></size>",
  ui_story_30090401_A3_dialog_content = "<size=37><color=#FFFFFF>Míralo y espera a que se abra por sí solo.</color></size>",
  ui_story_30090401_X55_dialog_content = "<size=37><color=#FFFFFF>...</color></size>",
  ui_story_30090401_54_dialog_content = "<size=37><color=#FFFFFF>10. Wispy necesita ser alimentado todos los días. La hora de alimentación es al mediodía.</color></size>",
  ui_story_30090401_A4_dialog_content = "<size=37><color=#FFFFFF>La maleta debe estar abierta para alimentar a Wispy. Consulta la nota #3 para saber cómo abrir la caja.</color></size>",
  ui_story_30090401_X57_dialog_content = "<size=37><color=#FFFFFF>Si te pierdes la hora de alimentación, algo terrible sucederá.</color></size>",
  ui_story_30090401_A5_dialog_content = "<size=37><color=#FFFFFF>No quieres descubrir qué es.</color></size>",
  ui_story_30090401_55_dialog_content = "*Cierra*",
  ui_story_30090401_56_dialog_content = "*Levanta la cabeza* Sigo sintiendo como si me hubiera mirado...",
  ui_story_30090401_57_dialog_content = "La limpieza diaria y la prevención de enfermedades están completas. Puedo marcar esas casillas.",
  ui_story_30090401_58_dialog_content = "Esto no es una tarea fácil en absoluto. Solo la limpieza me agotó.",
  ui_story_30090401_59_dialog_content = "Como si estuviera equipada con un motor, esta caja tiembla violentamente cada vez que se toca.",
  ui_story_30090401_60_dialog_content = "¿Me pregunto qué hay dentro?",
  ui_story_30090401_61_dialog_content = "Queda una cosa en la lista: alimentar.",
  ui_story_30090401_62_dialog_content = "Según la lista, Wispy come—",
  ui_story_30090401_63_dialog_content = "Pesadillas, recuerdos tristes, maldiciones mortales, fe desesperada y agua helada.",
  ui_story_30090401_64_dialog_content = "¿Pero dónde voy a encontrar todas estas cosas extrañas? Así que, solo logré preparar un poco de agua helada.",
  ui_story_30090401_65_dialog_content = "Pero entonces hay otro problema. Según la lista, debería mirarlo y esperar a que se abra por sí solo.",
  ui_story_30090401_66_dialog_content = "Pero ha pasado una hora y mis ojos están tensos. No parece que vayan a abrirse.",
  ui_story_30090401_67_dialog_content = "...",
  ui_story_30090401_68_dialog_content = "...",
  ui_story_30090401_69_option_content = "Ábrelo a la fuerza",
  ui_story_30090401_70_dialog_content = "Parece que tengo que usar la fuerza.",
  ui_story_30090401_71_dialog_content = "*Intenta abrir la caja*",
  ui_story_30090401_72_dialog_content = "<color=#e8d9bb>La maleta se abre un poco.</color>",
  ui_story_30090401_73_dialog_content = "¡Creo que está funcionando! Espera...",
  ui_story_30090401_74_dialog_content = "Mi dedo se quedó atrapado, ¡duele!!!!",
  ui_story_30090401_75_dialog_content = "Esto no va a funcionar.",
  ui_story_30090401_76_option_content = "Sigue mirando",
  ui_story_30090401_77_dialog_content = "*Mira*",
  ui_story_30090401_78_dialog_content = "*Sigue mirando*",
  ui_story_30090401_79_dialog_content = "...",
  ui_story_30090401_X79_dialog_content = "Mis ojos están tan secos que siento que se van a caer...",
  ui_story_30090401_80_dialog_content = "Me rindo.",
  ui_story_30090401_81_dialog_content = "Debería ir a hacer otra cosa.",
  ui_story_30090401_82_dialog_content = "*Abre sigilosamente*",
  ui_story_30090401_83_dialog_content = "*Cierra*",
  ui_story_30090401_84_dialog_content = "¿Me lo imaginé? Lo que sea, me voy.",
  ui_story_30090401_85_dialog_content = "*Se abre un poco más*",
  ui_story_30090401_86_dialog_content = "...",
  ui_story_30090401_87_dialog_content = "¡Ja, te atrapé!!",
  ui_story_30090401_88_dialog_content = "Pasé toda la hora mirándote y no te abriste, pero una vez que me di la vuelta y me fui, te abriste por tu cuenta. ¡Eres tan difícil de tratar!",
  ui_story_30090401_89_dialog_content = "Apúrate y bebe el agua helada, luego déjame ver qué hay... dentro de ti...",
  ui_story_30090401_90_dialog_content = "¡Vaya! ¿Qué es esto?!",
  ui_story_30090401_91_dialog_content = "<color=#e8d9bb>Aterrada, la maleta se cierra por sí misma y tiembla violentamente durante un tiempo antes de calmarse.</color>",
  ui_story_30090401_92_dialog_content = "Mechones rojos, y creo que vi un par de ojos muy grandes y brillantes...",
  ui_story_30090401_93_dialog_content = "¿Está Faust guardando un pulpo allí?",
  ui_story_30090401_94_dialog_content = "Oh no, no se abre de nuevo, ¿cómo voy a alimentarlo...",
  ui_story_30090401_95_dialog_content = "¡Oh sí! ¡La lista de cuidados!",
  ui_story_30090401_96_dialog_content = "\"... Si Wispy está siendo absolutamente terco, intenta calmarlo elogiándolo.\"",
  ui_story_30090401_97_dialog_content = "Una caja que necesita consuelo... ridículo...",
  ui_story_30090401_98_dialog_content = "*Sacude violentamente de nuevo*",
  ui_story_30090401_99_dialog_content = "Lo siento, lo siento.",
  ui_story_30090401_100_dialog_content = "Ejem, linda cajita, te conseguí esta agua helada extremadamente deliciosa y fresca!",
  ui_story_30090401_101_dialog_content = "Por favor, abrir.",
  ui_story_30090401_102_dialog_content = "*Se queda quieto*",
  ui_story_30090401_103_dialog_content = "¿Cajita? ¿Linda cajita?",
  ui_story_30090401_104_dialog_content = "Ah, ¿qué voy a hacer?",
  ui_story_30090401_105_dialog_content = "No puedo ni cuidar de una caja, ¿cómo voy a enfrentarme a Faust cuando regrese?",
  ui_story_30090401_106_dialog_content = "Estoy tan triste, voy a llorar.",
  ui_story_30090401_107_dialog_content = "*Se abre lentamente y extiende los mechones*",
  ui_story_30090401_108_dialog_content = "Eh...",
  ui_story_30090401_109_dialog_content = "*Acaricia con mechones*",
  ui_story_30090401_110_dialog_content = "¿Me estás tranquilizando? Gracias...",
  ui_story_30090401_111_dialog_content = "¿Por qué también estás llorando? ¿Quién iba a pensar que una extraña caja podría empatizar?",
  ui_story_30090401_112_dialog_content = "*Mueve ligeramente los mechones, como si estuviera de acuerdo*",
  ui_story_30090401_113_dialog_content = "No sé por qué, pero siento tu calidez.",
  ui_story_30090401_114_dialog_content = "Gracias Wispy, tú tampoco deberías sentirte triste.",
  ui_story_30090401_115_dialog_content = "No es triste.",
  ui_story_30090401_116_dialog_content = "¿Oh? Faust, ¿has vuelto?",
  ui_story_30090401_117_dialog_content = "Sí, tomó un tiempo.",
  ui_story_30090401_118_dialog_content = "Tuve que tratar a mis adorables creyentes con la máxima sinceridad.",
  ui_story_30090401_X118_dialog_content = "Aunque usé una caja falsa, nadie lo sabía.",
  ui_story_30090401_119_dialog_content = "Saqué las baratijas de la caja y las repartí. Todos los creyentes lloraron lágrimas de alegría.",
  ui_story_30090401_120_dialog_content = "Pude hacer eso gracias a ti por cuidar de Wispy por mí.",
  ui_story_30090401_121_dialog_content = "Gracias, pero aún siento pena por hacer llorar a Wispy.",
  ui_story_30090401_122_dialog_content = "No, esas no eran lágrimas.",
  ui_story_30090401_123_dialog_content = "<color=#FFB400>Los recuerdos tristes son la comida favorita de Wispy</color>. Solo tenía hambre.",
  ui_story_30090401_124_dialog_content = "Entonces... ¿Vio mi tristeza y desesperación y babeó?",
  ui_story_30090401_125_dialog_content = "Desafortunadamente, me temo que sí.",
  ui_story_30090401_126_dialog_content = "*Mueve los mechones felizmente*",
  ui_story_30090401_127_dialog_content = "Ya veo.",
  ui_story_30090401_128_dialog_content = "<size=45>Ehh—</size>",
  ui_story_30090401_129_dialog_content = "<color=#e8d9bb>Wispy es como un gato, tiene personalidad. Trátalo con delicadeza.</color>",
  ui_story_30090601_1_dialog_content = "El mercado de Twin Pavilions Bay... Este lugar parece estar siempre lleno de ajetreo, día y noche.",
  ui_story_30090601_2_dialog_content = "¿Eh? Esa persona al frente parece...",
  ui_story_30090601_3_dialog_content = "No todos los días tenemos a un joven tan guapo ojeando nuestros productos. Te diré qué, te daré un descuento del veinte por ciento en cualquiera de estos libros que te gusten.",
  ui_story_30090601_4_dialog_content = "Gracias por el amable gesto, señora.",
  ui_story_30090601_5_dialog_content = "Si estos libros antiguos ayudan a arrojar algo de luz sobre la verdad, estaría eternamente agradecido por tu amabilidad.",
  ui_story_30090601_6_dialog_content = "¡Eres educado, verdad! Jeje... Ha pasado un tiempo desde que alguien me llamó \"señora\".",
  ui_story_30090601_7_dialog_content = "Por cierto, tengo bastantes libros antiguos incompletos en mi tienda. ¿Te interesaría echar un vistazo, joven?",
  ui_story_30090601_8_dialog_content = "Por supuesto, me encantaría echar un vistazo, si eso está bien para ti.",
  ui_story_30090601_9_dialog_content = "Al principio, no estaba muy seguro por ese atuendo, pero ese comportamiento y esa forma de hablar...",
  ui_story_30090601_10_dialog_content = "Faust, realmente eres tú.",
  ui_story_30090601_11_dialog_content = "¿PlayerName? No pensé que te encontraría aquí. Qué agradable sorpresa.",
  ui_story_30090601_12_dialog_content = "¿Qué estás haciendo aquí? ¿Y qué pasa con todos los libros?",
  ui_story_30090601_13_dialog_content = "Recientemente he estado estudiando la antigua cultura de Longzhou.",
  ui_story_30090601_14_dialog_content = "Y descubro que la mejor manera de estudiar una cultura es sumergirse en ella.",
  ui_story_30090601_15_dialog_content = "Para entender completamente la importancia de la ropa, la comida y los modales de una cultura, uno debe experimentarlos personalmente.",
  ui_story_30090601_16_dialog_content = "Así que recientemente, he estado aquí en Twin Pavilions Bay, reuniendo una serie de libros antiguos y reliquias culturales de Longzhou.",
  ui_story_30090601_17_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_30090601_18_dialog_content = "Aquí, estos son todos nuestros antiguos textos mezclados.",
  ui_story_30090601_19_dialog_content = "De todos modos, nadie ha querido quitármelos de las manos después de todo este tiempo, así que si los quieres, solo tómalos todos, gratis.",
  ui_story_30090601_20_dialog_content = "<size=45>¡Hay tantos de ellos!</size>",
  ui_story_30090601_21_dialog_content = "Pero realmente están todos en pedazos. Ni siquiera una sola página de estos libros está intacta. ¿Todavía puedes leerlos...?",
  ui_story_30090601_22_dialog_content = "Nunca olvidaré su generosidad, señora.",
  ui_story_30090601_23_dialog_content = "Ahora, por favor permíteme colocar estos libros antiguos en mi maleta.",
  ui_story_30090601_24_dialog_content = "¡Espera! No hagas algo tan peligroso frente a todas estas personas.",
  ui_story_30090601_25_dialog_content = "¿Dónde te estás quedando ahora? Déjame ayudarte a llevarlos.",
  ui_story_30090601_26_dialog_content = "Ciertamente. Muchas gracias.",
  ui_story_30090601_27_dialog_content = "Vaya... Tienes libros y todo tipo de cosas esparcidas por aquí. Realmente no te andas con rodeos cuando se trata de estudiar, ¿verdad?",
  ui_story_30090601_28_dialog_content = "Bueno, Longzhou tiene una historia muy larga y es un vasto territorio rico en recursos.",
  ui_story_30090601_29_dialog_content = "Explorar los orígenes de tales asuntos no es algo que se pueda lograr de la noche a la mañana.",
  ui_story_30090601_30_dialog_content = "El antiguo guión de Longzhou es un tema que requiere un estudio minucioso en sí mismo.",
  ui_story_30090601_31_dialog_content = "La formación de caracteres implica pictografía, ideogramas, asociación, pictofonética...",
  ui_story_30090601_32_dialog_content = "Las palabras que una vez expresaron un cierto significado pueden haber evolucionado a una forma completamente diferente en textos escritos diez o cien años después.",
  ui_story_30090601_33_dialog_content = "Toma estos textos antiguos básicos que leí recientemente, por ejemplo.",
  ui_story_30090601_34_dialog_content = "Este personaje aquí originalmente tenía múltiples significados.",
  ui_story_30090601_35_dialog_content = "Pero en textos posteriores, fue modificado con diferentes radicales.",
  ui_story_30090601_36_dialog_content = "Al agregar estos componentes radicales, el carácter original desarrolló una gama de nuevos significados...",
  ui_story_30090601_37_dialog_content = "¿Radicales?",
  ui_story_30090601_38_dialog_content = "Déjame escribir algunos para que veas.",
  ui_story_30090601_39_dialog_content = "(Él incluso tiene todos los pinceles de caligrafía y papel especial listos. Supongo que hablaba en serio cuando dijo que se estaba sumergiendo en la cultura.)",
  ui_story_30090601_40_dialog_content = "(¡Y... en realidad es bastante bueno en eso!)",
  ui_story_30090601_41_dialog_content = "Así como esto, puedes ramificarte en múltiples significados que originalmente eran representados por un solo personaje.",
  ui_story_30090601_42_dialog_content = "Aunque este sistema es muy intrincado, también puede llevar fácilmente a la confusión.",
  ui_story_30090601_43_dialog_content = "¿Este carácter aquí significa \"abrir\"... o significa \"establecer\"?",
  ui_story_30090601_44_dialog_content = "¿Hmm? ¿Has estudiado esto antes?",
  ui_story_30090601_45_dialog_content = "No, es solo que he escuchado que la mayoría de las cosas en Longzhou están de alguna manera relacionadas con los sentidos.",
  ui_story_30090601_46_dialog_content = "Entonces, este carácter se coloca dentro del radical que representa una puerta, así que supongo que el significado debería ser algo similar a abrir una puerta... ¿Verdad?",
  ui_story_30090601_47_dialog_content = "Y este contiene esa pequeña parte que indica movimiento... entonces, ¿podría estar relacionado con la idea de... \"evasión\"?",
  ui_story_30090601_48_dialog_content = "Eso es precisamente correcto.",
  ui_story_30090601_49_dialog_content = "¡Debo decir, muestras un nivel excepcional de talento natural para esto!",
  ui_story_30090601_50_dialog_content = "Vamos, no sé mucho acerca de estos personajes.",
  ui_story_30090601_51_dialog_content = "Probablemente sea solo porque he hecho muchos amigos de Longzhou recientemente y he aprendido algunas cosas interesantes de ellos sin darme cuenta.",
  ui_story_30090601_52_dialog_content = "Eso es solo uno de tus muchos superpoderes.",
  ui_story_30090601_53_dialog_content = "Me pregunto, ¿podría usar tus conexiones sociales en algún momento en el futuro para realizar algún trabajo de campo en Longzhou?",
  ui_story_30090601_54_dialog_content = "Quizás también hay personas en ese gran continente interesadas en aprender sobre nuestra riqueza de conocimientos y muchas verdades.",
  ui_story_30090601_55_dialog_content = "... Lo sabía.",
  ui_story_30090601_56_dialog_content = "Supongo que podrían verlo simplemente como compartir información y promover la comunicación entre nuestros dos continentes... Debería estar bien.",
  ui_story_30090601_57_dialog_content = "Entonces permíteme agradecerte de antemano por tu amabilidad.",
  ui_story_30090601_58_dialog_content = "Y como muestra de gratitud...",
  ui_story_30090601_59_dialog_content = "¿Has desarrollado algún interés en la antigua caligrafía de Longzhou, no es así?",
  ui_story_30090601_60_dialog_content = "¿Te gustaría que te enseñe cómo escribir estos caracteres?",
  ui_story_30090601_61_dialog_content = "<size=45>¿Eh? ¿En serio?</size>Pero todos estos caracteres parecen tan complicados...",
  ui_story_30090601_62_dialog_content = "Solo a través de la acción podemos empujar la puerta de la verdad.",
  ui_story_30090601_63_dialog_content = "Por favor—toma asiento.",
  ui_story_30090601_64_dialog_content = "Estoy totalmente a favor de tomar acción, pero ¿cómo se supone que debo usar esta brocha? La punta es tan suave, apenas puedo controlarla...",
  ui_story_30090601_65_dialog_content = "¡Ah! ¡He manchado tinta por todo el lugar!",
  ui_story_30090601_66_dialog_content = "No entres en pánico.",
  ui_story_30090601_67_dialog_content = "Tal escritura no debe ser apresurada o ejecutada descuidadamente, y no debe haber rastro de incertidumbre en tu corazón.",
  ui_story_30090601_68_dialog_content = "Tu pincel debe marcar el papel como una piedra que cae resueltamente desde la cima de una montaña, extenderse horizontalmente, como nubes que se alargan por mil millas, y deslizarse verticalmente, como una vid eterna, trepando por toda la eternidad...",
  ui_story_30090601_69_dialog_content = "Sigue el impulso del pincel y encontrarás que los caracteres se forman por sí mismos, naturalmente.",
  ui_story_30090601_70_dialog_content = "Puntea el papel, como una piedra cayendo desde la cima de una montaña.",
  ui_story_30090601_71_dialog_content = "Extiéndete horizontalmente, como nubes que se extienden por mil millas.",
  ui_story_30090601_72_dialog_content = "Deslízate verticalmente, como una vid trepando hacia la eternidad...",
  ui_story_30090601_73_dialog_content = "¡Creo que estoy entendiendo esto! Producir hermosos trazos realmente no es tan difícil como parece.",
  ui_story_30090601_74_dialog_content = "Pero... Todavía creo que mis personajes no están exactamente al mismo nivel que los tuyos.",
  ui_story_30090601_75_dialog_content = "Es como si estas pinceladas que acabo de pintar ni siquiera constituyeran una sola palabra.",
  ui_story_30090601_76_dialog_content = "Mmm...",
  ui_story_30090601_77_dialog_content = "¿Qué crees que son las \"palabras\" en esencia?",
  ui_story_30090601_78_option_content = "Supongo que realmente nunca lo había pensado antes.",
  ui_story_30090601_79_dialog_content = "De hecho, cuanto más comúnmente se usa algo, más probable es que pasemos por alto su significado.",
  ui_story_30090601_80_option_content = "Son cosas verdaderamente asombrosas.",
  ui_story_30090601_81_dialog_content = "Buena respuesta.",
  ui_story_30090601_82_dialog_content = "Aunque estamos bastante acostumbrados a encontrarnos constantemente rodeados de palabras.",
  ui_story_30090601_83_dialog_content = "En mis ojos, su mera existencia es un precioso milagro para maravillarse a diario.",
  ui_story_30090601_84_dialog_content = "Antes te preguntaste cuál era el propósito de comprar estos viejos libros rotos.",
  ui_story_30090601_85_dialog_content = "Ahora, te diré por qué los compré.",
  ui_story_30090601_86_dialog_content = "Es porque las palabras son chispas de verdad.",
  ui_story_30090601_87_dialog_content = "A través de las palabras, se puede preservar y acumular el conocimiento de aquellos que nos precedieron.",
  ui_story_30090601_88_dialog_content = "Trascendiendo las mareas del tiempo, se convierten en un poema que puede ser recitado mil años después.",
  ui_story_30090601_89_dialog_content = "Aunque son fragmentos, igual que el fuego nace de simples cenizas—",
  ui_story_30090601_90_dialog_content = "Estas chispas dispersas poseen la capacidad de provocar una tormenta furiosa con solo un poco de ayuda.",
  ui_story_30090601_91_dialog_content = "Cada frase, cada palabra, cada carácter del pasado podría ser potencialmente una señal dejada por nuestros predecesores en su camino hacia la verdad.",
  ui_story_30090601_92_dialog_content = "Por supuesto, un legado así vale la pena apreciar y explorar.",
  ui_story_30090601_93_dialog_content = "¡Claro!",
  ui_story_30090601_94_dialog_content = "Entonces, cuando escribas estos caracteres, no te concentres demasiado en tus pinceladas.",
  ui_story_30090601_95_dialog_content = "Pregúntate por qué este personaje posee tal forma y qué significado podría tener.",
  ui_story_30090601_96_dialog_content = "La audacia de \"abrir\" y la humildad de \"evadir\"... Todo reside en tus trazos.",
  ui_story_30090601_97_dialog_content = "Para estos personajes, esto es lo más importante.",
  ui_story_30090601_98_dialog_content = "¡Ya veo!",
  ui_story_30090601_99_dialog_content = "La caligrafía es en realidad muy similar a mis habilidades psíquicas. No se trata solo de lo que puedes ver...",
  ui_story_30090601_100_dialog_content = "El mismo propósito de su existencia es transmitir más de lo que se puede ver solo con el ojo.",
  ui_story_30090601_101_dialog_content = "Ahora que también entiendes esta profunda verdad, creo que podrás escribir con mayor confianza.",
  ui_story_30090601_102_dialog_content = "¡Sí! Gracias, Faust.",
  ui_story_30090601_103_dialog_content = "También debes buscar entender la importancia de las palabras en relación con la verdad.",
  ui_story_30090601_104_dialog_content = "¡Correcto!",
  ui_story_30090601_105_dialog_content = "Entonces, eso significa que seguramente estás dispuesto a unirte a la Orden Verdadera y buscar la verdad última como uno de nuestros miembros.",
  ui_story_30090601_106_dialog_content = "Sí... No lo creo.",
  ui_story_30090601_107_dialog_content = "Casi me atrapas allí.",
  ui_story_30090601_108_dialog_content = "Suspiro... Pensé que podría funcionar esa vez. Qué lástima.",
  ui_story_30090601_109_dialog_content = "Se está haciendo tarde. Terminemos nuestra pequeña sesión de estudio por hoy.",
  ui_story_30090601_110_dialog_content = "De ninguna manera... ¿No me has invitado ahora mismo para intentar hacerme unir a la Orden Verdadera, verdad?!",
  ui_story_30090601_111_dialog_content = "Jaja... ¿De verdad crees que haría algo así?",
  ui_story_30090601_112_dialog_content = "... ¿No lo haces?",
  ui_story_30090601_113_dialog_content = "Independientemente de mis intenciones, fue muy agradable intercambiar conocimientos sobre historia y cultura contigo.",
  ui_story_30090601_114_dialog_content = "Y solo echa un vistazo a la maravillosa caligrafía que has producido aquí hoy.",
  ui_story_30090601_115_dialog_content = "Ver tu progreso a este nivel en tan corto período de tiempo me da una satisfacción tremenda como profesor.",
  ui_story_30090601_116_dialog_content = "Gracias por permitirme disfrutar de una tarde tan satisfactoria.",
  ui_story_30090601_117_dialog_content = "Ehm... Debería agradecerte por ser tan paciente conmigo. Realmente aprendí mucho hoy.",
  ui_story_30090601_118_dialog_content = "Bueno, si realmente estás agradecido, ¿podría hacerte una pequeña solicitud?",
  ui_story_30090601_119_dialog_content = "¡No me voy a unir a la True Order!",
  ui_story_30090601_120_dialog_content = "Está bien... Parece que tendré que ir con mi segunda opción.",
  ui_story_30090601_121_dialog_content = "¿De verdad quiero saber qué es esta \"segunda opción\"...?",
  ui_story_30090601_122_dialog_content = "Si realmente voy a Longzhou en el futuro, ¿podrías acompañarme para apreciar las obras maestras de caligrafía producidas por los renombrados maestros de esa tierra lejana?",
  ui_story_30090601_123_dialog_content = "¡Bueno, eso es algo que puedo hacer! ¡Estoy deseando que llegue!",
  ui_story_30090601_124_dialog_content = "Antes de eso, sin embargo... ¿crees que todavía podría molestarte para que me enseñes un poco más de caligrafía?",
  ui_story_30090601_125_dialog_content = "Eres bienvenido a pasar cuando quieras."
